let intentText = '';
try {
  intentText = $('Set: Business Profile').first()?.json?.intent || '';
} catch (e) {}

const intentLower = (intentText || '').toLowerCase();
const isBroadIntent = !intentLower || intentLower.includes('all') || intentLower.includes('comprehensive');

const expectB1 = isBroadIntent || ['recommend', 'loan', 'option', 'best', 'scheme', 'policy'].some(k => intentLower.includes(k));
const expectB2 = isBroadIntent || ['afford', 'emi', 'cash flow', 'stress', 'bank', 'statement'].some(k => intentLower.includes(k));
const expectB3 = isBroadIntent || ['contract', 'sanction', 'clause', 'charge', 'fee', 'kfs', 'penalty'].some(k => intentLower.includes(k));
const expectB4 = isBroadIntent || ['prepay', 'invest', 'lump', 'amortization', 'saving'].some(k => intentLower.includes(k));

let f1Node = null;
let f2Node = null;
let f3Node = null;
let f4Node = null;

try { f1Node = $('AI Agent: Loan Recommender').first()?.json; } catch (e) {}
try { f2Node = $('Code: Stress Scenarios').first()?.json; } catch (e) {}
try { f3Node = $('AI Agent: Contract Checker').first()?.json; } catch (e) {}
try { f4Node = $('Code: Compare to Invest').first()?.json; } catch (e) {}

const b1Ready = !expectB1 || !!f1Node;
const b2Ready = !expectB2 || !!f2Node;
const b3Ready = !expectB3 || !!f3Node;
const b4Ready = !expectB4 || !!f4Node;

if (!b1Ready || !b2Ready || !b3Ready || !b4Ready) {
  return [];
}

let loanRec = null;
let b1Status = 'skipped';
if (expectB1) {
  if (f1Node) {
    if (f1Node.error) {
      b1Status = 'failed';
      loanRec = { error: f1Node.error.message || 'Loan recommender agent encountered an error.' };
    } else {
      b1Status = 'completed';
      loanRec = f1Node.output || f1Node.loan_recommendation || f1Node.text || f1Node;
    }
  } else {
    b1Status = 'missing';
  }
}

let affordability = null;
let b2Status = 'skipped';
if (expectB2) {
  if (f2Node) {
    if (f2Node.error) {
      b2Status = 'failed';
      affordability = { error: f2Node.error.message || 'Affordability evaluation failed.' };
    } else {
      b2Status = 'completed';
      affordability = f2Node.affordability_verdict || f2Node;
    }
  } else {
    b2Status = 'missing';
  }
}

let flaggedClauses = null;
let b3Status = 'skipped';
if (expectB3) {
  if (f3Node) {
    if (f3Node.error) {
      b3Status = 'failed';
      flaggedClauses = { error: f3Node.error.message || 'Contract audit agent encountered an error.' };
    } else {
      b3Status = 'completed';
      flaggedClauses = f3Node.output || f3Node.flagged_clauses || f3Node.text || f3Node;
    }
  } else {
    b3Status = 'missing';
  }
}

let prepayVsInvest = null;
let b4Status = 'skipped';
if (expectB4) {
  if (f4Node) {
    if (f4Node.error) {
      b4Status = 'failed';
      prepayVsInvest = { error: f4Node.error.message || 'Prepayment evaluation failed.' };
    } else {
      b4Status = 'completed';
      prepayVsInvest = f4Node.prepay_vs_invest_comparison || f4Node;
    }
  } else {
    b4Status = 'missing';
  }
}

const branchStatus = {
  branch_1_loan_recommender: b1Status,
  branch_2_affordability: b2Status,
  branch_3_contract_audit: b3Status,
  branch_4_prepayment_invest: b4Status,
};

const branchesExecuted = Object.keys(branchStatus).filter(k => branchStatus[k] === 'completed');
const branchesFailed = Object.keys(branchStatus).filter(k => branchStatus[k] === 'failed');

return [{
  json: {
    loan_recommendation: loanRec,
    affordability_verdict: affordability,
    flagged_clauses: flaggedClauses,
    prepay_vs_invest_comparison: prepayVsInvest,
    meta: {
      branch_status: branchStatus,
      branches_executed: branchesExecuted,
      branches_failed: branchesFailed,
      all_expected_succeeded: branchesFailed.length === 0
    }
  }
}];

const items = $input.all();
let transactions = [];
let profile = {};
try { profile = $('Set: Business Profile').first()?.json || {}; } catch(e) {}

for (const item of items) {
  if (item.json && item.json.transactions && Array.isArray(item.json.transactions)) {
    transactions = item.json.transactions;
  }
}

if (transactions.length === 0) {
  const amountNeeded = Number(profile.amount_needed) || 1000000;
  const avgInc = Number(profile.avg_monthly_income) || Math.round(amountNeeded * 0.45);
  const avgExp = Number(profile.avg_monthly_expense) || Math.round(avgInc * 0.70);

  transactions = [
    { month: 'M-1', income: Math.round(avgInc * 0.95), expense: Math.round(avgExp * 0.98) },
    { month: 'M-2', income: Math.round(avgInc * 1.05), expense: Math.round(avgExp * 1.02) },
    { month: 'M-3', income: Math.round(avgInc * 1.00), expense: Math.round(avgExp * 1.00) },
    { month: 'M-4', income: Math.round(avgInc * 0.90), expense: Math.round(avgExp * 0.95) },
    { month: 'M-5', income: Math.round(avgInc * 1.10), expense: Math.round(avgExp * 1.05) },
    { month: 'M-6', income: Math.round(avgInc * 1.00), expense: Math.round(avgExp * 1.00) }
  ];
}

const surpluses = transactions.map(t => (Number(t.income) || 0) - (Number(t.expense) || 0));
const totalSurplus = surpluses.reduce((a, b) => a + b, 0);
const avgSurplus = surpluses.length > 0 ? Math.round(totalSurplus / surpluses.length) : 0;
const minSurplus = surpluses.length > 0 ? Math.min(...surpluses) : 0;
const totalIncome = transactions.reduce((sum, t) => sum + (Number(t.income) || 0), 0);
const avgIncome = Math.round(totalIncome / (transactions.length || 1));

return [{
  json: {
    monthly_transactions: transactions,
    surpluses: surpluses,
    average_monthly_income: avgIncome,
    average_monthly_surplus: avgSurplus,
    minimum_monthly_surplus: minSurplus
  }
}];

const cashFlow = $input.first().json;
let profile = {};
try { profile = $('Set: Business Profile').first().json || {}; } catch(e) {}

const amountNeeded = Number(profile.amount_needed) || 1000000;
const proposedEmi = Number(profile.proposed_emi) || Math.round(amountNeeded * 0.025);
const emergencyShockAmount = Number(profile.emergency_shock_amount) || 50000;

const avgSurplus = cashFlow.average_monthly_surplus || 150000;
const avgIncome = cashFlow.average_monthly_income || 500000;

const revDrop20Surplus = Math.round(avgSurplus - (avgIncome * 0.20));
const revDrop30Surplus = Math.round(avgSurplus - (avgIncome * 0.30));
const delay30DaysSurplus = Math.round(avgSurplus * 0.70);
const shockExpenseSurplus = Math.round(avgSurplus - emergencyShockAmount);

const scenarios = [
  {
    name: 'Baseline Surplus',
    surplus: avgSurplus,
    passed: avgSurplus >= proposedEmi,
    cushion: avgSurplus - proposedEmi,
    description: 'Historical average monthly net surplus'
  },
  {
    name: 'Revenue Shock -20%',
    surplus: revDrop20Surplus,
    passed: revDrop20Surplus >= proposedEmi,
    cushion: revDrop20Surplus - proposedEmi,
    description: '20% drop in monthly turnover'
  },
  {
    name: 'Revenue Shock -30%',
    surplus: revDrop30Surplus,
    passed: revDrop30Surplus >= proposedEmi,
    cushion: revDrop30Surplus - proposedEmi,
    description: '30% catastrophic revenue collapse'
  },
  {
    name: '30-Day Payment Delay (Liquidity Haircut)',
    surplus: delay30DaysSurplus,
    passed: delay30DaysSurplus >= proposedEmi,
    cushion: delay30DaysSurplus - proposedEmi,
    description: 'Working capital realization delay'
  },
  {
    name: 'Emergency Expense Shock',
    surplus: shockExpenseSurplus,
    passed: shockExpenseSurplus >= proposedEmi,
    cushion: shockExpenseSurplus - proposedEmi,
    description: `One-off unplanned expense of ₹${emergencyShockAmount}`
  }
];

const failedTests = scenarios.filter(s => !s.passed);
const failedCount = failedTests.length;

let verdict = 'affordable';
let riskLevel = 'Low';
let summary = 'Sufficient cash flow cushion across all stress scenarios.';

if (proposedEmi > avgSurplus || failedCount >= 3) {
  verdict = 'not_affordable';
  riskLevel = 'High';
  summary = `High default risk: Proposed EMI of ₹${proposedEmi} fails ${failedCount}/5 stress shocks.`;
} else if (failedCount >= 1) {
  verdict = 'risky';
  riskLevel = 'Medium';
  summary = `Moderate vulnerability: Proposed EMI is serviceable in baseline, but fails ${failedCount} stress shock(s) (${failedTests.map(f => f.name).join(', ')}).`;
}

const suggestedEmiCeiling = Math.max(0, Math.round(Math.min(avgSurplus * 0.60, revDrop20Surplus * 0.80)));
const dscrProxy = proposedEmi > 0 ? Number((avgSurplus / proposedEmi).toFixed(2)) : 999;

return [{
  json: {
    affordability_verdict: {
      proposed_emi: proposedEmi,
      verdict: verdict,
      risk_level: riskLevel,
      suggested_emi_ceiling: suggestedEmiCeiling,
      dscr_proxy: dscrProxy,
      summary: summary,
      stress_scenarios: scenarios,
      failed_shock_count: failedCount
    }
  }
}];

