parameters.jsCode:
const input = $input.first().json;
let profile = {};
try { profile = $('Set: Business Profile').first().json || {}; } catch(e) {}

const principal = Number(input.principal_remaining || profile.principal_remaining || profile.amount_needed) || 1000000;
const annualRate = Number(input.interest_rate || profile.interest_rate) || 12;
const totalMonths = Number(input.tenure_remaining_months || profile.tenure_remaining_months) || 36;
const lumpSum = Number(input.lump_sum_available || profile.lump_sum_available) || 300000;
const expectedInvestRate = Number(input.expected_investment_return_rate || profile.expected_investment_return_rate) || 10;
const taxRate = profile.tax_rate !== undefined ? Number(profile.tax_rate) : 0.25;

const monthlyRate = annualRate / (12 * 100);

let emi = 0;
if (monthlyRate === 0) {
  emi = Math.round(principal / totalMonths);
} else {
  const factor = Math.pow(1 + monthlyRate, totalMonths);
  emi = Math.round((principal * monthlyRate * factor) / (factor - 1));
}

let baselineBalance = principal;
let baselineTotalInterest = 0;
for (let m = 1; m <= totalMonths; m++) {
  const interest = monthlyRate > 0 ? baselineBalance * monthlyRate : 0;
  const principalPaid = Math.min(baselineBalance, emi - interest);
  baselineTotalInterest += interest;
  baselineBalance -= principalPaid;
}

const effectiveLumpSum = Math.min(principal, lumpSum);
const newPrincipal = Math.max(0, principal - effectiveLumpSum);

let prepaidTotalInterest = 0;
let prepaidMonths = 0;
let prepayBalance = newPrincipal;

if (newPrincipal > 0) {
  while (prepayBalance > 1 && prepaidMonths < totalMonths) {
    prepaidMonths++;
    const interest = monthlyRate > 0 ? prepayBalance * monthlyRate : 0;
    const principalPaid = Math.min(prepayBalance, emi - interest);
    prepaidTotalInterest += interest;
    prepayBalance -= principalPaid;
    if (principalPaid <= 0) break;
  }
}

const grossInterestSaved = Math.round(Math.max(0, baselineTotalInterest - prepaidTotalInterest));
const afterTaxInterestSaved = Math.round(grossInterestSaved * (1 - taxRate));
const tenureReducedMonths = totalMonths - prepaidMonths;

return [{
  json: {
    principal_remaining: principal,
    interest_rate: annualRate,
    tenure_remaining_months: totalMonths,
    lump_sum_applied: effectiveLumpSum,
    monthly_emi: emi,
    baseline_total_interest: Math.round(baselineTotalInterest),
    prepaid_total_interest: Math.round(prepaidTotalInterest),
    gross_interest_saved: grossInterestSaved,
    after_tax_interest_saved: afterTaxInterestSaved,
    original_tenure_months: totalMonths,
    new_tenure_months: prepaidMonths,
    tenure_reduced_months: tenureReducedMonths,
    expected_investment_return_rate: expectedInvestRate,
    tax_rate: taxRate
  }
}];

const prepay = $input.first().json;
let profile = {};
try { profile = $('Set: Business Profile').first().json || {}; } catch(e) {}

const lumpSum = prepay.lump_sum_applied || Number(profile.lump_sum_available) || 300000;
const returnRate = prepay.expected_investment_return_rate || Number(profile.expected_investment_return_rate) || 10;
const horizonYears = (prepay.original_tenure_months || 36) / 12;
const taxRate = prepay.tax_rate !== undefined ? prepay.tax_rate : 0.25;
const investTaxRate = 0.125; // 12.5% LTCG

const futureValueGross = Math.round(lumpSum * Math.pow(1 + (returnRate / 100), horizonYears));
const grossGain = Math.max(0, futureValueGross - lumpSum);
const afterTaxGain = Math.round(grossGain * (1 - investTaxRate));
const afterTaxInterestSaved = prepay.after_tax_interest_saved || Math.round((prepay.gross_interest_saved || 0) * (1 - taxRate));

let recommendation = '';
let riskNote = '';

if (afterTaxInterestSaved > afterTaxGain) {
  const diff = afterTaxInterestSaved - afterTaxGain;
  recommendation = `Prepay Loan: Guaranteed risk-free after-tax savings of ₹${afterTaxInterestSaved.toLocaleString('en-IN')} exceed projected after-tax investment gains by ₹${diff.toLocaleString('en-IN')}.`;
  riskNote = 'Prepayment offers 100% risk-free return and immediately strengthens balance sheet liquidity.';
} else {
  const diff = afterTaxGain - afterTaxInterestSaved;
  recommendation = `Invest Surplus: Projected after-tax investment gain of ₹${afterTaxGain.toLocaleString('en-IN')} exceeds loan interest savings by ₹${diff.toLocaleString('en-IN')}.`;
  riskNote = 'Notice: Investment returns carry market risk, while loan prepayment yields guaranteed risk-free savings.';
}

return [{
  json: {
    prepay_vs_invest_comparison: {
      lump_sum_amount: lumpSum,
      time_horizon_years: horizonYears,
      prepayment: {
        gross_interest_saved: prepay.gross_interest_saved || 0,
        after_tax_interest_saved: afterTaxInterestSaved,
        tenure_reduced_months: prepay.tenure_reduced_months || 0
      },
      investment: {
        expected_annual_return_pct: returnRate,
        gross_gain: grossGain,
        after_tax_gain: afterTaxGain,
        projected_future_value: futureValueGross
      },
      recommendation: recommendation,
      risk_disclaimer: riskNote
    }
  }
}];

let triggeredBy = 'manual_chat';

try {
  if ($('Webhook Trigger').first()?.json) {
    triggeredBy = 'webhook';
  }
} catch (e) {}

if (triggeredBy === 'manual_chat') {
  try {
    if ($('Execute Workflow Trigger').first()?.json) {
      triggeredBy = 'orchestrator';
    }
  } catch (e) {}
}

if (triggeredBy === 'manual_chat' && $execution.mode === 'webhook') {
  triggeredBy = 'webhook';
}

const item = $input.first()?.json || {};

return [{
  json: {
    ...item,
    triggered_by: triggeredBy
  }
}];

const inputData = $input.first()?.json || {};

const branchesExecuted = inputData.meta?.branches_executed || [];
const branchesFailed = inputData.meta?.branches_failed || [];
const branchStatus = inputData.meta?.branch_status || {};
const hasError = branchesFailed.length > 0 || !!inputData.error;

return [{
  json: {
    status: hasError ? (branchesExecuted.length > 0 ? 'partial_success' : 'error') : 'success',
    workflow: 'Credit Agent Workflow',
    branches_executed: branchesExecuted,
    branches_failed: branchesFailed,
    branch_status: branchStatus,
    report: inputData.output || '',
    data: {
      loan_recommendation: inputData.loan_recommendation || null,
      affordability_verdict: inputData.affordability_verdict || null,
      flagged_clauses: inputData.flagged_clauses || null,
      prepay_vs_invest_comparison: inputData.prepay_vs_invest_comparison || null
    },
    timestamp: new Date().toISOString()
  }
}];

