const input = $input.first().json;
const principal = Number(input.principal_remaining) || 1000000;
const annualRate = Number(input.interest_rate) || 12;
const monthlyRate = annualRate / 12 / 100;
const totalMonths = Number(input.tenure_remaining_months) || 36;
const lumpSum = Number(input.lump_sum_available) || 300000;

const emi = principal * (monthlyRate * Math.pow(1 + monthlyRate, totalMonths)) / (Math.pow(1 + monthlyRate, totalMonths) - 1);
const totalPaymentNoPrepay = emi * totalMonths;
const totalInterestNoPrepay = totalPaymentNoPrepay - principal;

const newPrincipal = Math.max(0, principal - lumpSum);
let totalInterestWithPrepay = 0;
let monthsWithPrepay = 0;
let currentBalance = newPrincipal;

while (currentBalance > 0 && monthsWithPrepay < totalMonths) {
  const interestForMonth = currentBalance * monthlyRate;
  const principalForMonth = Math.min(currentBalance, emi - interestForMonth);
  totalInterestWithPrepay += interestForMonth;
  currentBalance -= principalForMonth;
  monthsWithPrepay++;
}

const interestSaved = Math.round(totalInterestNoPrepay - totalInterestWithPrepay);
const tenureReducedMonths = totalMonths - monthsWithPrepay;

return [{
  json: {
    principal_remaining: principal,
    interest_rate: annualRate,
    tenure_remaining_months: totalMonths,
    lump_sum_applied: lumpSum,
    monthly_emi: Math.round(emi),
    baseline_total_interest: Math.round(totalInterestNoPrepay),
    prepaid_total_interest: Math.round(totalInterestWithPrepay),
    interest_saved: interestSaved,
    original_tenure_months: totalMonths,
    new_tenure_months: monthsWithPrepay,
    tenure_reduced_months: tenureReducedMonths
  }
}];

