try { termsInput = $('Loan Terms Input').first().json || {}; } catch(e) {}

const lumpSum = prepay.lump_sum_applied || Number(termsInput.lump_sum_available) || 300000;
const returnRate = Number(termsInput.expected_investment_return_rate) || 10;
const horizonYears = (prepay.original_tenure_months || 36) / 12;

const futureValueInvestment = lumpSum * Math.pow(1 + (returnRate / 100), horizonYears);
const investmentGain = Math.round(futureValueInvestment - lumpSum);
const interestSavedPrepayment = prepay.interest_saved || 0;

let recommendation = '';
if (interestSavedPrepayment > investmentGain) {
  recommendation = 'Prepayment provides guaranteed higher savings than expected investment return.';
} else {
  recommendation = 'Investment projected return is higher, but carries market risk; prepayment savings are 100% guaranteed risk-free.';
}

return [{
  json: {
    prepay_vs_invest_comparison: {
      lump_sum_amount: lumpSum,
      time_horizon_years: horizonYears,
      prepayment: {
        interest_saved_guaranteed: interestSavedPrepayment,
        tenure_reduced_months: prepay.tenure_reduced_months
      },
      investment: {
        expected_annual_return_pct: returnRate,
        projected_investment_gain: investmentGain,
        projected_total_value: Math.round(futureValueInvestment)
      },
      net_difference: Math.abs(interestSavedPrepayment - investmentGain),
      recommendation: recommendation,
      risk_disclaimer: 'Note: Investment returns are subject to market risks and not guaranteed. Loan prepayment savings represent a guaranteed, tax-free return on capital equal to the loan interest rate.'
    }
  }
}];

let triggeredBy = 'manual_chat';

try {
  if ($('Webhook Trigger').first()?.json) {
    triggeredBy = 'webhook';
  }
} catch (e) {}

if (triggeredBy === 'manual_chat') {
  try {
    if ($('Execute Workflow Trigger').first()?.json) {
      triggeredBy = 'orchestrator';
    }
  } catch (e) {}
}

if (triggeredBy === 'manual_chat' && $execution.mode === 'webhook') {
  triggeredBy = 'webhook';
}

const item = $input.first()?.json || {};

return [{
  json: {
    ...item,
    triggered_by: triggeredBy
  }
}];

const inputData = $input.first()?.json || {};

const branchesExecuted = [];
if (inputData.loan_recommendation) branchesExecuted.push('loan_recommendation');
if (inputData.affordability_verdict) branchesExecuted.push('affordability_verdict');
if (inputData.flagged_clauses) branchesExecuted.push('flagged_clauses');
if (inputData.prepay_vs_invest_comparison) branchesExecuted.push('prepay_vs_invest_comparison');

const hasError = !!inputData.error;

return [{
  json: {
    status: hasError ? 'error' : 'success',
    workflow: 'Credit Agent Workflow',
    branches_executed: branchesExecuted,
    report: inputData.output || '',
    data: {
      loan_recommendation: inputData.loan_recommendation || null,
      affordability_verdict: inputData.affordability_verdict || null,
      flagged_clauses: inputData.flagged_clauses || null,
      prepay_vs_invest_comparison: inputData.prepay_vs_invest_comparison || null
    },
    timestamp: new Date().toISOString()
  }
}];
